788	  useEffect(() => {
789	    setQty(Number(item.quantidade) || 0);
790	  }, [item.id, item.quantidade]);
791	
792	  const unidade = ficha.rendimento_unidade || item.unidade || 'g';
793	  const custoUnit = ficha.rendimento_quantidade > 0
794	    ? (Number(ficha.custo_calculado) || 0) / ficha.rendimento_quantidade
795	    : 0;
796	  const custo = custoUnit * qty;
797	
798	  const handleSave = async () => {
799	    if (item.id == null || qty <= 0) {
800	      toast.error('Informe a quantidade');
801	      return;
802	    }
803	    setSaving(true);
804	    try {
805	      // Trigger do banco recomputa o custo da receita final automaticamente
806	      const { error } = await supabase
807	        .from('ficha_tecnica_itens')
808	        .update({ quantidade: qty, unidade })
809	        .eq('id', item.id);
810	      if (error) throw error;
811	      toast.success('Consumo atualizado — custo recalculado');
812	    } catch (err) {
813	      toast.error(err instanceof Error ? err.message : 'Erro ao salvar consumo');
814	    } finally {
815	      setSaving(false);
816	    }
817	  };
818	
819	  const abrirReceitaCompleta = () => {
820	    window.dispatchEvent(
821	      new CustomEvent('configurator:focar-ficha', { detail: { ficha_id: ficha.id } })
822	    );
823	  };
824	
825	  return (
826	    <aside className="absolute top-14 right-0 bottom-0 w-[420px] z-20 bg-white dark:bg-slate-900 border-l border-border shadow-2xl overflow-y-auto animate-in slide-in-from-right duration-300">
827	      <header className="sticky top-0 bg-white dark:bg-slate-900 border-b border-border p-4 flex items-center justify-between z-10">
828	        <div className="flex items-center gap-2 min-w-0">
829	          <ChefHat className="h-5 w-5 text-emerald-500 shrink-0" />
830	          <div className="min-w-0">
831	            <h2 className="font-semibold text-sm truncate">{ficha.nome}</h2>
832	            <span className="inline-flex items-center gap-1 mt-0.5 px-1.5 py-0.5 rounded-full bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-300 text-[9px] font-bold uppercase tracking-wider">
833	              Sub-receita de {parentNome}
834	            </span>
835	          </div>
836	        </div>
837	        <button onClick={onClose} className="text-muted-foreground hover:text-foreground" aria-label="Fechar">
838	          <X className="h-4 w-4" />
839	        </button>
840	      </header>
841	
842	      <div className="p-4 space-y-4">
843	        {/* Custo unitário da sub-receita */}
844	        <div className="rounded-lg bg-emerald-50 dark:bg-emerald-900/20 p-3">
845	          <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Custo da sub-receita</p>
846	          <p className="text-lg font-bold text-emerald-700 dark:text-emerald-300 tabular-nums">
847	            {fmtBRL(custoUnit)} <span className="text-xs font-normal">/ {unidade}</span>
848	          </p>
849	          <p className="text-[10px] text-muted-foreground tabular-nums">
850	            rende {ficha.rendimento_quantidade} {ficha.rendimento_unidade} · total {fmtBRL(Number(ficha.custo_calculado) || 0)}
851	          </p>
852	        </div>
853	
854	        {/* Consumo na receita final — editável */}
855	        <div className="rounded-lg border-2 border-amber-300 dark:border-amber-700/50 bg-amber-50/60 dark:bg-amber-950/20 p-3 space-y-2">
856	          <p className="text-[10px] uppercase tracking-wider text-amber-700 dark:text-amber-300 font-bold">
857	            Quanto vai em {parentNome}
858	          </p>
859	          <div className="flex items-end gap-2">
860	            <div className="flex-1 space-y-0.5">
861	              <Label className="text-[10px] text-muted-foreground">Quantidade</Label>
862	              <div className="flex items-center gap-1">
863	                <Input
864	                  type="number" min={0} step="0.01"
865	                  className="h-8 text-sm"
866	                  value={qty || ''}
867	                  onChange={(e) => setQty(Number(e.target.value) || 0)}
868	                  onKeyDown={(e) => { if (e.key === 'Enter' && qty > 0 && !saving) handleSave(); }}
869	                />
870	                <span className="text-xs text-muted-foreground shrink-0 min-w-[28px]">{unidade}</span>
871	              </div>
872	            </div>
873	            <Button size="sm" className="h-8" onClick={handleSave} disabled={saving || qty <= 0}>
874	              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />}
875	            </Button>
876	          </div>
877	          {custo > 0 && (
878	            <p className="text-[11px] text-emerald-700 dark:text-emerald-300 font-medium tabular-nums">
