801	export function CmvBottomToolbar({ onSavePosition }: CmvBottomToolbarProps) {
802	  const { zoomIn, zoomOut, fitView, setCenter, setNodes, getNodes, getEdges } = useReactFlow();
803	  const [isLocked, setIsLocked] = useState(false);
804	  const [isOrganizing, setIsOrganizing] = useState(false);
805	
806	  const handleLayout = async () => {
807	    setIsOrganizing(true);
808	    const nodes = getNodes();
809	    const edges = getEdges();
810	    const layoutedNodes = layoutGraph(nodes, edges, 'LR');
811	    
812	    setNodes(layoutedNodes);
813	    window.requestAnimationFrame(() => {
814	      fitView({ duration: 600, padding: 0.2 });
815	    });
816	
817	    if (onSavePosition) {
818	      for (const node of layoutedNodes) {
819	        if (!node.id.startsWith('nf_nota_')) {
820	          await onSavePosition(node.id, node.position.x, node.position.y);
821	        }
822	      }
823	    }
824	    setIsOrganizing(false);
825	  };
826	
827	  const handleToggleLock = () => {
828	    const newLocked = !isLocked;
829	    setIsLocked(newLocked);
830	    setNodes(nds => nds.map(n => ({ ...n, draggable: !newLocked })));
831	  };
832	
833	  return (
834	    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20">
835	      <div className="flex items-center gap-1 rounded-2xl bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-white/40 dark:border-white/10 shadow-2xl px-2 py-1.5 animate-in fade-in slide-in-from-bottom-4 duration-300">
836	        <button className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]" title="Zoom +" onClick={() => zoomIn({ duration: 300 })}>
837	          <ZoomIn size={18} />
838	        </button>
839	        <button className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]" title="Zoom -" onClick={() => zoomOut({ duration: 300 })}>
840	          <ZoomOut size={18} />
841	        </button>
842	        
843	        <div className="w-px h-6 bg-[#57715B]/10 mx-0.5" />
844	        
845	        <button className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]" title="Ajustar à tela" onClick={() => fitView({ duration: 600, padding: 0.2 })}>
846	          <Maximize2 size={18} />
847	        </button>
848	        <button className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]" title="Centralizar" onClick={() => setCenter(0, 0, { zoom: 1, duration: 600 })}>
849	          <Crosshair size={18} />
850	        </button>
851	        <button 
852	          className={`h-9 w-9 rounded-lg flex items-center justify-center transition-all ${isOrganizing ? 'bg-[#57715B] text-white shadow-md hover:bg-[#465b49]' : 'text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]'}`} 
853	          title="Organizar nodes" 
854	          onClick={handleLayout}
855	          disabled={isOrganizing}
856	        >
857	          <LayoutGrid size={18} className={isOrganizing ? "animate-pulse" : ""} />
858	        </button>
859	        
860	        <div className="w-px h-6 bg-[#57715B]/10 mx-0.5" />
861	        
862	        <button 
863	          className={`h-9 w-9 rounded-lg flex items-center justify-center transition-all ${isLocked ? 'bg-[#57715B] text-white shadow-md hover:bg-[#465b49]' : 'text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]'}`} 
864	          title={isLocked ? "Desbloquear" : "Bloquear"} 
865	          onClick={handleToggleLock}
866	        >
867	          {isLocked ? <Lock size={18} /> : <Unlock size={18} />}
868	        </button>
869	        <button className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]" title="Reset view" onClick={() => fitView({ duration: 0 })}>
870	          <RotateCcw size={18} />
871	        </button>
872	      </div>
873	    </div>
874	  );
875	}
