import { useState } from 'react';
import { Package, DollarSign } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { Command, CommandInput, CommandEmpty, CommandGroup, CommandItem, CommandList } from '@/shared/ui/command';
import { Input } from '@/shared/ui/input';
import { Button } from '@/shared/ui/button';
import { ScrollArea } from '@/shared/ui/scroll-area';

interface CmvNodePaletteProps {
  embalagens: Array<{ id: number; nome: string; preco_custo: number | null; unidade_medida: string | null }>;
  onAddEmbalagem: (embalagemId: number) => Promise<void>;
  onAddAvulso: (nome: string, valor: number) => Promise<void>;
}

interface PaletteButtonProps {
  icon: React.ReactNode;
  label: string;
  color: 'blue' | 'orange';
  onClick: () => void;
}

function PaletteButton({ icon, label, color, onClick }: PaletteButtonProps) {
  const colors = {
    blue: 'text-blue-500',
    orange: 'text-orange-500',
  };
  return (
    <button
      onClick={onClick}
      className="flex flex-col items-center gap-1 p-2 rounded-xl hover:bg-[#57715B]/5 transition-colors group"
      title={label}
    >
      <div
        className={`p-2 rounded-lg bg-white/60 dark:bg-black/20 shadow-sm border border-[#57715B]/10 group-hover:scale-110 transition-transform ${colors[color]}`}
      >
        {icon}
      </div>
      <span className="text-[9px] font-medium text-slate-600 dark:text-slate-400">{label}</span>
    </button>
  );
}

export function CmvNodePalette({ embalagens, onAddEmbalagem, onAddAvulso }: CmvNodePaletteProps) {
  const [embOpen, setEmbOpen] = useState(false);
  const [avulsoOpen, setAvulsoOpen] = useState(false);
  const [avulsoNome, setAvulsoNome] = useState('');
  const [avulsoValor, setAvulsoValor] = useState('');

  const handleAddAvulsoClick = () => {
    if (!avulsoNome || !avulsoValor) return;
    onAddAvulso(avulsoNome, parseFloat(avulsoValor));
    setAvulsoOpen(false);
    setAvulsoNome('');
    setAvulsoValor('');
  };

  return (
    <div className="absolute top-20 left-3 z-20">
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-white/40 dark:border-white/10 shadow-xl p-2 rounded-2xl flex flex-col gap-1">
        <div className="text-[8px] font-bold uppercase tracking-wider text-[#57715B] text-center pb-1 border-b border-[#57715B]/10 mb-1.5">
          Adicionar
        </div>

        <Popover open={embOpen} onOpenChange={setEmbOpen}>
          <PopoverTrigger asChild>
            <div>
              <PaletteButton
                icon={<Package size={18} />}
                label="Embalagem"
                color="blue"
                onClick={() => setEmbOpen(true)}
              />
            </div>
          </PopoverTrigger>
          <PopoverContent
            side="right"
            align="start"
            className="w-[min(300px,calc(100vw-2rem))] p-0 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl ml-2"
          >
            <Command>
              <CommandInput placeholder="Buscar embalagem..." />
              <CommandList>
                <ScrollArea className="h-52">
                  <CommandEmpty>Nenhuma embalagem encontrada.</CommandEmpty>
                  <CommandGroup>
                    {embalagens.map((emb) => (
                      <CommandItem
                        key={emb.id}
                        onSelect={() => {
                          onAddEmbalagem(emb.id);
                          setEmbOpen(false);
                        }}
                      >
                        {emb.nome}
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </ScrollArea>
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>

        <Popover open={avulsoOpen} onOpenChange={setAvulsoOpen}>
          <PopoverTrigger asChild>
            <div>
              <PaletteButton
                icon={<DollarSign size={18} />}
                label="Avulso"
                color="orange"
                onClick={() => setAvulsoOpen(true)}
              />
            </div>
          </PopoverTrigger>
          <PopoverContent
            side="right"
            align="start"
            className="w-[min(280px,calc(100vw-2rem))] p-3 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl ml-2 flex flex-col gap-3"
          >
            <div className="space-y-1">
              <label className="text-xs font-medium text-slate-700 dark:text-slate-300">
                Nome do custo
              </label>
              <Input
                placeholder="Nome do custo..."
                value={avulsoNome}
                onChange={(e) => setAvulsoNome(e.target.value)}
                className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-medium text-slate-700 dark:text-slate-300">
                Valor (R$)
              </label>
              <Input
                type="number"
                placeholder="0.00"
                value={avulsoValor}
                onChange={(e) => setAvulsoValor(e.target.value)}
                className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
              />
            </div>
            <Button
              onClick={handleAddAvulsoClick}
              disabled={!avulsoNome || !avulsoValor}
              className="w-full bg-[#57715B] hover:bg-[#465b49] text-white"
            >
              Adicionar
            </Button>
          </PopoverContent>
        </Popover>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Dialog, DialogContent } from '@/shared/ui/dialog';
import { Input } from '@/shared/ui/input';
import { Button } from '@/shared/ui/button';
import { Receipt, Search, ChevronRight, Loader2, Check } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

interface CmvAtrelarNFDialogProps {
  open: boolean;
  cmvItemId: number | null;
  embalagemNome: string | null;
  currentNfItemId: number | null;
  onClose: () => void;
  onSaved: () => void;
}

type NF = {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
};

type NFItem = {
  id: number;
  nota_id: number;
  nome_produto: string | null;
  quantidade: number | null;
  valor_unitario: number | null;
  subtotal: number | null;
  insumo_id: number | null;
};

export function CmvAtrelarNFDialog({
  open,
  cmvItemId,
  embalagemNome,
  currentNfItemId,
  onClose,
  onSaved,
}: CmvAtrelarNFDialogProps) {
  const [step, setStep] = useState<'pickNF' | 'pickItem'>('pickNF');
  const [nfs, setNfs] = useState<NF[]>([]);
  const [nfItems, setNfItems] = useState<NFItem[]>([]);
  const [pickedNF, setPickedNF] = useState<NF | null>(null);
  const [busca, setBusca] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) {
      setStep('pickNF');
      setPickedNF(null);
      setBusca('');
      fetchNFs();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const fetchNFs = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('notas_fiscais')
      .select('id, fornecedor, numero_nota, valor_total, data_nota')
      .order('data_nota', { ascending: false })
      .limit(80);

    if (error) {
      toast.error('Erro ao buscar notas fiscais: ' + error.message);
    } else {
      setNfs((data ?? []) as NF[]);
    }
    setLoading(false);
  };

  const fetchItems = async (nfId: number) => {
    setLoading(true);
    const { data, error } = await supabase
      .from('itens_nota_fiscal')
      .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id')
      .eq('nota_id', nfId);

    if (error) {
      toast.error('Erro ao buscar itens da nota: ' + error.message);
    } else {
      setNfItems((data ?? []) as NFItem[]);
    }
    setLoading(false);
  };

  const handlePickNF = (nf: NF) => {
    setPickedNF(nf);
    setBusca('');
    setStep('pickItem');
    fetchItems(nf.id);
  };

  const handlePickItem = async (item: NFItem) => {
    if (!cmvItemId) return;
    setSaving(true);

    const { error } = await supabase
      .from('cmv_itens')
      .update({ nf_item_id: item.id, preco_unitario_esboco: null } as Record<string, unknown>)
      .eq('id', cmvItemId);

    setSaving(false);

    if (error) {
      toast.error('Erro ao atrelar NF: ' + error.message);
    } else {
      toast.success('Nota fiscal atrelada com sucesso');
      onSaved();
      onClose();
    }
  };

  const filteredNFs = nfs.filter(
    (n) =>
      (n.fornecedor?.toLowerCase() ?? '').includes(busca.toLowerCase()) ||
      (n.numero_nota?.toLowerCase() ?? '').includes(busca.toLowerCase()),
  );

  const filteredItems = nfItems.filter((i) =>
    (i.nome_produto?.toLowerCase() ?? '').includes(busca.toLowerCase()),
  );

  const formatDate = (d: string | null) => {
    if (!d) return '';
    try {
      return new Date(d).toLocaleDateString('pt-BR');
    } catch {
      return d;
    }
  };

  const formatMoney = (v: number | null) => {
    if (v === null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  return (
    <Dialog open={open} onOpenChange={(val) => !val && onClose()}>
      <DialogContent className="max-w-2xl max-h-[82vh] flex flex-col bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl p-0 overflow-hidden">
        <div className="p-4 border-b border-[#57715B]/10 flex flex-col gap-2 shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
              Atrelar Nota Fiscal a {embalagemNome ?? 'Embalagem'}
            </h2>
          </div>

          {step === 'pickItem' && pickedNF && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground mt-1">
              <Button
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs hover:bg-[#57715B]/10 text-[#57715B]"
                onClick={() => {
                  setStep('pickNF');
                  setBusca('');
                }}
              >
                Outra NF
              </Button>
              <ChevronRight size={14} />
              <span className="font-medium text-[#57715B]">
                NF {pickedNF.numero_nota} - {pickedNF.fornecedor}
              </span>
            </div>
          )}

          <div className="relative mt-2">
            <Search
              className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground"
              size={16}
            />
            <Input
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              placeholder={
                step === 'pickNF'
                  ? 'Buscar por fornecedor ou número...'
                  : 'Buscar por produto na nota...'
              }
              className="pl-9 bg-white/60 dark:bg-black/20 border-[#57715B]/15 rounded-xl focus-visible:ring-[#57715B]/30"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-2">
          {loading && (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="animate-spin text-[#57715B]" size={24} />
            </div>
          )}

          {!loading && step === 'pickNF' && (
            <div className="flex flex-col divide-y divide-[#57715B]/10">
              {filteredNFs.map((nf) => (
                <button
                  key={nf.id}
                  onClick={() => handlePickNF(nf)}
                  className="flex items-center justify-between p-3 text-left hover:bg-[#57715B]/5 transition-colors rounded-lg group"
                >
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-[#57715B]/10 rounded-lg text-[#57715B]">
                      <Receipt size={18} />
                    </div>
                    <div>
                      <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF] group-hover:text-[#57715B] transition-colors">
                        {nf.fornecedor ?? 'Desconhecido'}
                      </div>
                      <div className="text-xs text-muted-foreground">
                        NF: {nf.numero_nota} • Data: {formatDate(nf.data_nota)}
                      </div>
                    </div>
                  </div>
                  <div className="font-medium tabular-nums text-[#57715B]">
                    {formatMoney(nf.valor_total)}
                  </div>
                </button>
              ))}
              {filteredNFs.length === 0 && (
                <div className="p-8 text-center text-muted-foreground text-sm">
                  Nenhuma nota fiscal encontrada.
                </div>
              )}
            </div>
          )}

          {!loading && step === 'pickItem' && (
            <div className="flex flex-col gap-1">
              {filteredItems.map((item) => {
                const isAlreadyLinked = item.id === currentNfItemId;

                return (
                  <button
                    key={item.id}
                    disabled={saving}
                    onClick={() => handlePickItem(item)}
                    className={`flex items-center justify-between p-3 text-left transition-colors rounded-xl ${
                      isAlreadyLinked
                        ? 'border-l-4 border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20'
                        : 'hover:bg-[#57715B]/5'
                    }`}
                  >
                    <div className="flex-1 pr-4">
                      <div className="font-medium text-[#2D362E] dark:text-[#E6DCCF] flex items-center gap-2">
                        {item.nome_produto}
                        {isAlreadyLinked && <Check size={14} className="text-emerald-600" />}
                      </div>
                      <div className="text-xs text-muted-foreground mt-1">
                        {item.quantidade} un × {formatMoney(item.valor_unitario)}
                      </div>
                    </div>
                    <div className="font-bold text-[#57715B] tabular-nums whitespace-nowrap">
                      {formatMoney(item.subtotal ?? (item.quantidade ?? 0) * (item.valor_unitario ?? 0))}
                    </div>
                  </button>
                );
              })}
              {filteredItems.length === 0 && (
                <div className="p-8 text-center text-muted-foreground text-sm">
                  Nenhum item encontrado nesta nota.
                </div>
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

