import { useState, useEffect, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import {
  X,
  Package,
  DollarSign,
  ChefHat,
  Calculator,
  Receipt,
  Loader2,
  Save,
  Trash2,
  Calendar,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { CmvAtrelarNFDialog } from './CmvAtrelarNFDialog';
import type { RawCmvItem } from '@/features/financeiro/model/useCmvGraph';

interface CmvDetailPanelProps {
  selectedNodeId: string | null;
  cmv: {
    id: number;
    nome: string;
    status: string;
    custo_calculado: number | null;
  } | null;
  fichaData: {
    id: number;
    nome: string;
    custo_calculado: number | null;
    rendimento_quantidade: number;
    rendimento_unidade: string;
    status: string;
  } | null;
  items: RawCmvItem[];
  custoFichaUnitario: number;
  custoEmbalagens: number;
  custoAvulsos: number;
  custoTotal: number;
  nfEmbalagemItems: Array<{
    id: number;
    nota_id: number;
    nome_produto: string | null;
    valor_unitario: number | null;
    unidade: string | null;
    fornecedor: string | null;
    numero_nota: string | null;
    data_nota: string | null;
  }>;
  onClose: () => void;
  onRefetch: () => Promise<void>;
}

export function CmvDetailPanel({
  selectedNodeId,
  cmv,
  fichaData,
  items,
  custoFichaUnitario,
  custoEmbalagens,
  custoAvulsos,
  custoTotal,
  nfEmbalagemItems,
  onClose,
  onRefetch,
}: CmvDetailPanelProps) {
  const [atrelarNFOpen, setAtrelarNFOpen] = useState(false);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const formatMoney = (v: number | null | undefined) => {
    if (v == null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  const formatDate = (d: string | null) => {
    if (!d) return '';
    return new Date(d).toLocaleDateString('pt-BR');
  };

  const parsedId = selectedNodeId ? selectedNodeId.split('_') : [];
  const kind = parsedId[0];
  const kindId = parseInt(parsedId[1] || '0', 10);
  const isNotaNode = selectedNodeId?.startsWith('nf_nota_') ?? false;

  const selectedItem = useMemo(() => {
    if (kind === 'item' && kindId) return items.find((i) => i.id === kindId);
    return null;
  }, [kind, kindId, items]);

  const selectedNFItem = useMemo(() => {
    if (selectedItem?.nf_item_id) {
      return nfEmbalagemItems.find((n) => n.id === selectedItem.nf_item_id);
    }
    return null;
  }, [selectedItem, nfEmbalagemItems]);

  const selectedNotaNodesData = useMemo(() => {
    if (isNotaNode && parsedId[2]) {
      const notaId = parseInt(parsedId[2], 10);
      return nfEmbalagemItems.find((n) => n.nota_id === notaId);
    }
    return null;
  }, [isNotaNode, parsedId, nfEmbalagemItems]);

  useEffect(() => {
    if (selectedItem) {
      setEditQty(selectedItem.quantidade?.toString() ?? '');
      setEditUnit(selectedItem.unidade ?? '');
      setEditPreco(selectedItem.preco_unitario_esboco?.toString() ?? '');
      setEditObs(selectedItem.observacao ?? '');
      setEditUnidadesPorEmbalagem(selectedItem.unidades_por_embalagem?.toString() ?? '');
    }
  }, [selectedItem]);

  const handleSaveItem = async () => {
    if (!selectedItem) return;
    setIsSaving(true);

    const updates: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || 0,
      unidade: editUnit,
      observacao: editObs,
      unidades_por_embalagem: parseFloat(editUnidadesPorEmbalagem) || 1,
    };

    if (selectedItem.tipo === 'outro' || (selectedItem.tipo === 'embalagem' && !selectedItem.nf_item_id)) {
      updates.preco_unitario_esboco = parseFloat(editPreco) || 0;
    }

    const { error } = await supabase.from('cmv_itens').update(updates).eq('id', selectedItem.id);
    setIsSaving(false);

    if (error) {
      toast.error('Erro ao salvar: ' + error.message);
    } else {
      toast.success('Item atualizado');
      onRefetch();
    }
  };

  const handleDeleteItem = async () => {
    if (!selectedItem) return;
    if (!window.confirm('Tem certeza que deseja excluir este item?')) return;

    setIsDeleting(true);
    const { error } = await supabase.from('cmv_itens').delete().eq('id', selectedItem.id);
    setIsDeleting(false);

    if (error) {
      toast.error('Erro ao excluir: ' + error.message);
    } else {
      toast.success('Item excluído');
      onClose();
      onRefetch();
    }
  };

  const handleDesatrelarNF = async () => {
    if (!selectedItem) return;
    setIsSaving(true);
    const { error } = await supabase
      .from('cmv_itens')
      .update({ nf_item_id: null } as Record<string, unknown>)
      .eq('id', selectedItem.id);
    setIsSaving(false);
    if (error) {
      toast.error('Erro ao desatrelar: ' + error.message);
    } else {
      toast.success('NF desatrelada');
      onRefetch();
    }
  };

  if (!selectedNodeId) return null;

  return (
    <>
      <aside className="absolute top-14 right-0 bottom-0 w-full sm:w-[420px] z-20 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-l border-[#57715B]/10 shadow-2xl overflow-y-auto animate-in slide-in-from-right duration-300 flex flex-col">
        <header className="sticky top-0 bg-white/95 dark:bg-[#1A1A1A]/95 border-b border-[#57715B]/10 p-4 flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center gap-2">
            {kind === 'cmv' && <Calculator className="text-[#57715B]" size={20} />}
            {kind === 'ficha' && <ChefHat className="text-amber-500" size={20} />}
            {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
              <Package className="text-blue-500" size={20} />
            )}
            {kind === 'item' && selectedItem?.tipo === 'outro' && (
              <DollarSign className="text-orange-500" size={20} />
            )}
            {isNotaNode && <Receipt className="text-cyan-500" size={20} />}
            <span className="font-semibold text-sm">
              {kind === 'cmv' && 'Resumo do CMV'}
              {kind === 'ficha' && 'Ficha Base'}
              {kind === 'item' && selectedItem?.tipo === 'embalagem' && 'Detalhes da Embalagem'}
              {kind === 'item' && selectedItem?.tipo === 'outro' && 'Detalhes do Custo Avulso'}
              {isNotaNode && 'Detalhes da Nota Fiscal'}
            </span>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 hover:bg-[#57715B]/10"
            onClick={onClose}
          >
            <X size={18} className="text-muted-foreground" />
          </Button>
        </header>

        <div className="p-5 flex-1 overflow-y-auto space-y-6">
          {kind === 'cmv' && cmv && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">{cmv.nome}</h2>
              <div className="grid grid-cols-2 gap-3">
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Ficha Unitária
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoFichaUnitario)}
                  </span>
                </div>
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Embalagens
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoEmbalagens)}
                  </span>
                </div>
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Avulsos
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoAvulsos)}
                  </span>
                </div>
                <div className="bg-[#57715B]/10 rounded-2xl p-3 border border-[#57715B]/20 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-[#57715B] font-bold">
                    Custo Total
                  </span>
                  <span className="text-xl font-black tabular-nums text-[#57715B] mt-1">
                    {formatMoney(custoTotal)}
                  </span>
                </div>
              </div>
            </div>
          )}

          {kind === 'ficha' && fichaData && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">{fichaData.nome}</h2>
              <div className="flex items-center gap-2">
                <span className="text-amber-600 bg-amber-50 dark:bg-amber-900/20 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                  Rende: {fichaData.rendimento_quantidade} {fichaData.rendimento_unidade}
                </span>
                <span className="text-slate-600 bg-slate-100 dark:bg-slate-800 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                  {fichaData.status}
                </span>
              </div>
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 mt-4">
                <div className="text-xs uppercase tracking-wider text-muted-foreground font-semibold mb-1">
                  Custo Total da Ficha
                </div>
                <div className="text-3xl font-black tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {formatMoney(fichaData.custo_calculado)}
                </div>
                {fichaData.rendimento_quantidade > 0 && (
                  <div className="text-emerald-600 font-bold text-lg tabular-nums mt-4 pt-4 border-t border-[#57715B]/10">
                    {formatMoney(
                      (fichaData.custo_calculado ?? 0) / fichaData.rendimento_quantidade,
                    )}{' '}
                    / unidade
                  </div>
                )}
              </div>
            </div>
          )}

          {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-1">
                  {selectedItem.produtoMaster?.nome ??
                    selectedItem.insumo?.nome ??
                    selectedItem.observacao ??
                    'Embalagem'}
                </h2>
              </div>

              {selectedNFItem ? (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] uppercase tracking-wider text-[#57715B] font-bold flex items-center gap-1.5">
                      <Receipt size={12} /> NF Atrelada
                    </span>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 px-2 text-[10px] text-[#57715B] hover:bg-[#57715B]/10"
                      onClick={handleDesatrelarNF}
                      disabled={isSaving}
                    >
                      Usar valor fixo
                    </Button>
                  </div>
                  <div>
                    <div className="font-semibold text-sm">{selectedNFItem.fornecedor}</div>
                    <div className="text-xs text-muted-foreground flex items-center gap-2 mt-1">
                      <span>NF: {selectedNFItem.numero_nota}</span>
                      <span>•</span>
                      <span className="flex items-center gap-1">
                        <Calendar size={10} /> {formatDate(selectedNFItem.data_nota)}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-end justify-between pt-2 border-t border-[#57715B]/10">
                    <div className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                      {formatMoney(selectedNFItem.valor_unitario)}
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      Trocar NF
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold">
                      Valor Fixo
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5 text-[#57715B]"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      <Receipt size={12} className="mr-1.5" /> Atrelar NF
                    </Button>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Preço Unitário (R$)</Label>
                    <Input
                      type="number"
                      value={editPreco}
                      onChange={(e) => setEditPreco(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              )}

              <div className="space-y-4">
                <div className="space-y-1">
                  <Label className="text-xs">Unidades por pacote/caixa</Label>
                  <Input
                    type="number"
                    value={editUnidadesPorEmbalagem}
                    onChange={(e) => setEditUnidadesPorEmbalagem(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    placeholder="Ex: 100"
                  />
                  <p className="text-[10px] text-muted-foreground">
                    Quantas unidades vêm na embalagem comprada.
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label className="text-xs">Uso na Ficha (Qtd)</Label>
                    <Input
                      type="number"
                      value={editQty}
                      onChange={(e) => setEditQty(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Unidade de Uso</Label>
                    <Input
                      value={editUnit}
                      onChange={(e) => setEditUnit(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border border-emerald-500/20">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  Custo Calculado
                </span>
                <span className="text-xl font-black tabular-nums text-emerald-700 dark:text-emerald-400">
                  {formatMoney(selectedItem.custo_calculado)}
                </span>
              </div>
            </div>
          )}

          {kind === 'item' && selectedItem?.tipo === 'outro' && (
            <div className="space-y-6">
              <div className="space-y-1">
                <Label className="text-xs">Nome / Observação</Label>
                <Input
                  value={editObs}
                  onChange={(e) => setEditObs(e.target.value)}
                  className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                />
