import { useState } from 'react';
import { useReactFlow } from '@xyflow/react';
import { ZoomIn, ZoomOut, Maximize2, Crosshair, LayoutGrid, Lock, Unlock, RotateCcw } from 'lucide-react';
import { layoutGraph } from '@/components/producao/configurador/layout';

interface CmvBottomToolbarProps {
  onSavePosition?: (nodeId: string, x: number, y: number) => Promise<void>;
}

export function CmvBottomToolbar({ onSavePosition }: CmvBottomToolbarProps) {
  const { zoomIn, zoomOut, fitView, setCenter, setNodes, getNodes, getEdges } = useReactFlow();
  const [isLocked, setIsLocked] = useState(false);
  const [isOrganizing, setIsOrganizing] = useState(false);

  const handleLayout = async () => {
    setIsOrganizing(true);
    const currentNodes = getNodes();
    const currentEdges = getEdges();
    const layoutedNodes = layoutGraph(currentNodes, currentEdges, 'LR');

    setNodes(layoutedNodes);
    window.requestAnimationFrame(() => {
      fitView({ duration: 600, padding: 0.2 });
    });

    if (onSavePosition) {
      for (const node of layoutedNodes) {
        if (!node.id.startsWith('nf_nota_')) {
          await onSavePosition(node.id, node.position.x, node.position.y);
        }
      }
    }
    setIsOrganizing(false);
  };

  const handleToggleLock = () => {
    const newLocked = !isLocked;
    setIsLocked(newLocked);
    setNodes((nds) => nds.map((n) => ({ ...n, draggable: !newLocked })));
  };

  return (
    <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20">
      <div className="flex items-center gap-1 rounded-2xl bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-white/40 dark:border-white/10 shadow-2xl px-2 py-1.5 animate-in fade-in slide-in-from-bottom-4 duration-300">
        <button
          className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]"
          title="Zoom +"
          onClick={() => zoomIn({ duration: 300 })}
        >
          <ZoomIn size={18} />
        </button>
        <button
          className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]"
          title="Zoom -"
          onClick={() => zoomOut({ duration: 300 })}
        >
          <ZoomOut size={18} />
        </button>

        <div className="w-px h-6 bg-[#57715B]/10 mx-0.5" />

        <button
          className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]"
          title="Ajustar à tela"
          onClick={() => fitView({ duration: 600, padding: 0.2 })}
        >
          <Maximize2 size={18} />
        </button>
        <button
          className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]"
          title="Centralizar"
          onClick={() => setCenter(0, 0, { zoom: 1, duration: 600 })}
        >
          <Crosshair size={18} />
        </button>
        <button
          className={`h-9 w-9 rounded-lg flex items-center justify-center transition-all ${isOrganizing ? 'bg-[#57715B] text-white shadow-md hover:bg-[#465b49]' : 'text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]'}`}
          title="Organizar nodes"
          onClick={handleLayout}
          disabled={isOrganizing}
        >
          <LayoutGrid size={18} className={isOrganizing ? 'animate-pulse' : ''} />
        </button>

        <div className="w-px h-6 bg-[#57715B]/10 mx-0.5" />

        <button
          className={`h-9 w-9 rounded-lg flex items-center justify-center transition-all ${isLocked ? 'bg-[#57715B] text-white shadow-md hover:bg-[#465b49]' : 'text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]'}`}
          title={isLocked ? 'Desbloquear' : 'Bloquear'}
          onClick={handleToggleLock}
        >
          {isLocked ? <Lock size={18} /> : <Unlock size={18} />}
        </button>
        <button
          className="h-9 w-9 rounded-lg flex items-center justify-center transition-all text-slate-600 dark:text-slate-300 hover:bg-[#57715B]/10 hover:text-[#57715B]"
          title="Reset view"
          onClick={() => fitView({ duration: 0 })}
        >
          <RotateCcw size={18} />
        </button>
      </div>
    </div>
  );
}

